          if (lip) { ctx.fillStyle = '#ff52d0'; ctx.fillRect(X, Y, 16, 3); ctx.fillStyle = '#ffd0f0'; ctx.fillRect(X, Y, 16, 1); ctx.fillStyle = '#ffe84a'; ctx.fillRect(X + 5, Y + 5, 2, 2); ctx.fillRect(X + 9, Y + 5, 2, 2); }
