          ctx.fillStyle = '#9aa0b8'; ctx.fillRect(X, Y, 16, 1); ctx.fillRect(X, Y + 15, 16, 1);
          if (lip) { ctx.fillStyle = '#d0d4e8'; ctx.fillRect(X, Y, 16, 2); }
