          ctx.fillStyle = st ? '#6a563a' : '#28203a'; ctx.fillRect(X, Y + 15, 16, 1); ctx.fillRect(X + ((ty & 1) ? 8 : 0), Y, 1, 16);
          if (lip) { ctx.fillStyle = st ? '#f0dcae' : '#b8a8d8'; ctx.fillRect(X, Y, 16, 3); ctx.fillStyle = '#ffffff'; ctx.globalAlpha = 0.5; ctx.fillRect(X, Y, 16, 1); ctx.globalAlpha = 1; }
