          ctx.fillStyle = '#9a5238'; ctx.fillRect(X, Y, 16, 1);
          if (under) { ctx.fillStyle = '#c07858'; ctx.fillRect(X, Y + 13, 16, 3); ctx.fillStyle = '#f0dcae'; ctx.fillRect(X, Y + 15, 16, 1); }
