          ctx.fillStyle = 'rgba(0,0,0,0.35)'; for (let i = 0; i < 16; i += 8) { const yy = Y + ((i + (DD.G ? DD.G.frame : 0) / 2) % 16); ctx.fillRect(X + 2, yy, 12, 3); }
          ctx.fillStyle = '#ffffff'; ctx.fillRect(X + 2, Y, 1, 16); ctx.fillRect(X + 13, Y, 1, 16);
