          if (tx >= 192 + 24) { ctx.fillStyle = 'rgba(180,230,255,0.28)'; ctx.fillRect(X, Y, 16, 5); ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.fillRect(X + 2 + ((DD.G ? DD.G.frame >> 2 : 0) % 12), Y, 2, 16); }
